"Android and apps then behave as if it was never set. It can be put back from the Undo bar or from Changes.": "Android e le app si comporteranno come se non fosse mai stata impostata. Puoi ripristinarla dalla barra Annulla o da Modifiche.",
"Android asks whether this app may \"Run commands in Termux environment\".": "Android chiede se concedere a questa app l’autorizzazione “Run commands in Termux environment”.",
"Android builds the palette from your home-screen wallpaper (what it does by default).": "Android crea la tavolozza dallo sfondo della schermata Home (comportamento predefinito).",
"Android builds the whole palette from the color below.": "Android crea l’intera tavolozza dal colore qui sotto.",
"Android can't verify this APK's signature (edited after signing, or unsigned).": "Android non riesce a verificare la firma di questo APK (modificato dopo la firma oppure non firmato).",
"Android can't verify this APK's signature (edited after signing, or unsigned). It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Android non riesce a verificare la firma di questo APK (modificato dopo la firma oppure non firmato). Prima si tenta l’installazione così com’è; se Android la rifiuta, viene installata una copia firmata con la chiave di questa app.",
"Android is clearing the caches. This can take up to a minute or two; you can keep using the app.": "Android sta svuotando le cache. Può richiedere fino a un paio di minuti; puoi continuare a usare l’app.",
"Android keeps its settings behind the shell. Connect one of them in Working Modes, then come back.": "Android tiene le sue impostazioni dietro la shell. In Modalità operative connettine una, poi torna qui.",
"Android lists this overlay as unavailable": "Android indica questo overlay come non disponibile",
"Android lists this overlay as unavailable (its target app is missing, or it is not approved), so it cannot be switched.": "Android indica questo overlay come non disponibile (manca l’app target oppure non è approvato), quindi non può essere attivato o disattivato.",
"Android only uses a setting that something reads by that name. Leave the value empty to create it with nothing in it.": "Android usa un’impostazione solo se qualcosa la legge con quel nome. Lascia vuoto il valore per crearla senza alcun contenuto.",
