"Anthropic does not allow other apps to sign in with a Claude Pro or Max account. Claude Code, Anthropic's own tool, can: it runs in Termux, and the Terminal chats through it. With an API key saved, Claude Code uses the key instead.": "Anthropic non consente ad altre app di accedere con un account Claude Pro o Max. Claude Code, lo strumento ufficiale di Anthropic, invece può farlo: funziona in Termux e il Terminale lo usa per chattare. Con una chiave API salvata, Claude Code usa la chiave al suo posto.",
"Any screen density": "Qualsiasi densità dello schermo",
