"AnythingLLM runs on a computer or a server (Desktop or Docker). Enter its address (like http://192.168.1.20:3001/api/v1/openai) and an API key from AnythingLLM, Settings, Developer API. Each workspace shows up as a model.": "AnythingLLM funziona su un computer o un server (Desktop o Docker). Inserisci il suo indirizzo (ad es. http://192.168.1.20:3001/api/v1/openai) e una chiave API presa da AnythingLLM, Settings, Developer API. Ogni workspace appare come un modello.",
