"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMind è un server MCP: uno strumento che dà agli agenti AI il controllo di un dispositivo Android tramite ADB (app, file, log, screenshot). Da solo non è una chat.",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "DroidMind è installato in Debian. Avvialo con: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Aggiungilo al tuo agente come server MCP (il suo indirizzo viene stampato all’avvio).",
