"Edited": "Modificate",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "La modifica di un APK ne cambia il contenuto, quindi la firma non corrisponde più. Android non lo installerà finché non viene firmato di nuovo: usa Firma (questa app firma con una chiave propria).",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "La modifica di un APK ne cambia il contenuto, quindi la firma non corrisponde più. Android non lo installerà finché non viene firmato di nuovo; Firma lo fa con una chiave di questa app.",
"Effort": "Impegno",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "L’impegno cambia qualcosa solo per gli agenti la cui API ha questa opzione (Claude, ChatGPT, Gemini, Grok); per gli altri viene conservato ma non ha effetto quando si chatta con una chiave API, e nessuno di loro lo passa al proprio strumento di accesso in Termux.",
