"GPU load is not exposed the same way on every phone, so this may say \"Not available\" on yours.": "Il carico della GPU non viene esposto allo stesso modo su ogni telefono, quindi sul tuo potrebbe comparire “Non disponibile”.",
"GRANTED": "CONCESSO",
"Galaxy Store": "Galaxy Store",
"Galaxy Store updates for Samsung apps, and open-source updates for sideloaded apps from GitHub, Codeberg, F-Droid, IzzyOnDroid and Obtainium": "Aggiornamenti da Galaxy Store per le app Samsung e aggiornamenti open source per le app installate manualmente da GitHub, Codeberg, F-Droid, IzzyOnDroid e Obtainium",
"Game data (OBB)": "Dati di gioco (OBB)",
