"It could not be saved": "Impossibile salvare",
"It did not finish": "Non è terminato",
"It did not work": "Non ha funzionato",
"It finishes installing itself the first time it opens.": "Completa l’installazione la prima volta che viene aperto.",
"It goes back to the version that came with the phone. An older version often cannot use the data of a newer one, so it may lose its data.": "Torna alla versione fornita con il telefono. Una versione precedente spesso non riesce a usare i dati di una più recente, quindi potrebbe perdere i propri dati.",
"It has no Android build, so it goes into a Debian container inside Termux (several minutes, a few hundred MB). Already installed steps are skipped quickly.": "Non ha una versione per Android, quindi va in un container Debian dentro Termux (diversi minuti, qualche centinaio di MB). I passaggi già completati vengono saltati rapidamente.",
"It is not set any more": "Non è più impostata",
"It is removed for the device's user. A system app can be put back with Reinstall.": "Viene rimossa per l’utente del dispositivo. Un’app di sistema può essere ripristinata con Reinstalla.",
"It is removed for you. A system app stays on the phone and can be brought back with Reinstall.": "Viene rimossa per te. Un’app di sistema resta sul telefono e può essere recuperata con Reinstalla.",
"It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Prima si tenta l’installazione così com’è; se Android la rifiuta, viene installata una copia firmata con la chiave di questa app.",
"Its settings, accounts and files on the device are deleted.": "Le sue impostazioni, i suoi account e i suoi file sul dispositivo vengono eliminati.",
"Its settings, accounts, saved games and the files in its own storage are deleted. This cannot be undone.": "Le sue impostazioni, i suoi account, i salvataggi di gioco e i file nel suo spazio di archiviazione vengono eliminati. Non è possibile annullare l’operazione.",
"IzzyOnDroid": "IzzyOnDroid",
"IzzyOnDroid page": "Pagina di IzzyOnDroid",
"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan esegue modelli AI sul tuo computer, gratis. Sul computer: Jan, Settings, Local API Server: imposta l’host su 0.0.0.0 e avvialo, poi inserisci qui l’indirizzo del computer (ad es. http://192.168.1.20:1337/v1). Non esiste una versione di Jan per Android.",
