"Keys are encrypted with a key that stays in the phone's secure hardware, and they are only ever sent to their own provider's address. The page never sees them again after you type them; only the last four characters are shown.": "Le chiavi sono cifrate con una chiave che resta nell’hardware sicuro del telefono e vengono inviate solo all’indirizzo del rispettivo provider. Dopo che le hai digitate, la pagina non le vede più; vengono mostrati solo gli ultimi quattro caratteri.",
