"Lenovo": "Lenovo",
"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leon è un assistente personale open source (skill, voce) che funziona su un computer con Node.js e Python. Non ha una versione per Android e non è un agente di programmazione, quindi non chatta in questo Terminale.",
"Leon.ai": "Leon.ai",
"Let Termux take commands from other apps": "Consenti a Termux di accettare comandi da altre app",
"Let them act without asking": "Lasciali agire senza chiedere",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "Permette all’agente di leggere e scrivere file nella cartella indicata alla fine del comando (cambia /sdcard come preferisci).",
"Lets the agent think in explicit steps before it acts.": "Permette all’agente di ragionare per passaggi espliciti prima di agire.",
"Lets this app change a few protected system settings used by some advanced features.": "Permette a questa app di modificare alcune impostazioni di sistema protette usate da certe funzioni avanzate.",
"Lets this app install the package files you choose, such as APK, APKS and XAPK files from your storage.": "Permette a questa app di installare i file di pacchetto che scegli, come i file APK, APKS e XAPK dalla tua archiviazione.",
"Lets this app open another app's screen from the background, such as an app you have just installed.": "Permette a questa app di aprire la schermata di un’altra app mentre è in background, ad esempio un’app appena installata.",
