"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "Scegli un agente, poi il modello e l’impegno (Basso, Bilanciato o Alto: quanto gli viene chiesto di ragionare). La prima volta entrambi partono da una scelta bilanciata e l’agente chiede ciò che gli serve (una chiave API, un indirizzo di server o un accesso) e lo verifica prima che tu inizi.",
