"This app cannot read storage. Grant All-files access, or choose a font file by hand (that needs no access).": "Questa app non può leggere la memoria. Concedi l'accesso a tutti i file oppure scegli un file di carattere a mano (non serve alcun accesso).",
"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "Quest’app non richiede uno specifico touchscreen, tastiera o navigazione (non ha alcuna voce uses-configuration), quindi funziona con ciò che ha questo telefono.",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "Quest’app non elenca alcuna funzionalità hardware o software di cui ha bisogno (nessuna voce uses-feature).",
