"This app may not run commands in Termux yet.": "Quest’app potrebbe non poter ancora eseguire comandi in Termux.",
"This app now has its own private ADB key. Tap the mode badge for details.": "Questa app ora ha una propria chiave ADB privata. Tocca il badge della modalità per i dettagli.",
"This app's own shell - no root, ADB or package manager.": "La shell propria di quest’app: niente Root, ADB o gestore dei pacchetti.",
