"This needs the app build.": "Questo richiede la build dell’app.",
"This only works with the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); an agent used only with an API key cannot use one here.": "Funziona solo con gli agenti che accedono tramite il proprio strumento a riga di comando in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); un agente usato solo con una chiave API non può usarne uno qui.",
"This package carries data files that live outside the APK. Right after the install succeeds they are copied into place.": "Questo pacchetto contiene file di dati che si trovano fuori dall’APK. Subito dopo l’installazione riuscita vengono copiati al loro posto.",
