"To browse files on this phone, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "Per sfogliare i file di questo telefono, questa app richiede l’Accesso a tutti i file (oppure una modalità operativa: ADB, Shizuku o Root).",
