"To search storage for fonts, this app needs All-files access. You can also choose a font file by hand, which needs no access.": "Per cercare caratteri nella memoria, questa app ha bisogno dell'accesso a tutti i file. Puoi anche scegliere un file di carattere a mano, senza alcun accesso.",
